xpath.script:
(function() {
    var payBtn = document.getElementById('rzp-button1');
    if (!payBtn) return;

    var options = {
        "key": "rzp_test_mock_key_vantageops",
        "amount": Math.round(parseFloat('') * 100),
        "currency": "INR",
        "name": "VantageOps Commercial Suite",
        "description": "Quotation / Order  Payment",
        "image": "/web/static/img/favicon.ico",
        "handler": function (response){
            alert("✅ Mock Razorpay Payment Successful!\n\nPayment ID: " + (response.razorpay_payment_id || "pay_mock_9988776655") + "\nOrder: \nAmount: ₹");
            fetch('/vantage/portal/razorpay_callback', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {
                        order_id: "",
                        payment_id: response.razorpay_payment_id || "pay_mock_9988776655"
                    }
                })
            }).then(function() {
                window.location.reload();
            });
        },
        "prefill": {
            "name": "",
            "email": "",
            "contact": ""
        },
        "theme": {
            "color": "#714B67"
        }
    };

    payBtn.onclick = function(e){
        e.preventDefault();
        if (typeof Razorpay !== 'undefined') {
            var rzp1 = new Razorpay(options);
            rzp1.open();
        } else {
            // Fallback Mock Modal if script is blocked locally
            alert("⚡ Razorpay Gateway Modal Triggered!\n\nOrder: \nTotal: ₹\nSimulating instant payment approval...");
            options.handler({ razorpay_payment_id: "pay_mock_" + Math.floor(Math.random()*1000000000) });
        }
    }
})();

(function() {
    if (window.location.pathname.indexOf('/my/orders/') !== -1) {
        var card = document.getElementById('deal_negotiation_portal');
        if (!card) return;
        var currentRounds = card.getAttribute('data-rounds');
        var currentState = card.getAttribute('data-state');
        setInterval(function() {
            if (document.visibilityState === 'visible') {
                fetch(window.location.href, { headers: { 'X-Requested-With': 'XMLHttpRequest' } })
                    .then(function(res) { return res.text(); })
                    .then(function(html) {
                        var parser = new DOMParser();
                        var doc = parser.parseFromString(html, 'text/html');
                        var newCard = doc.getElementById('deal_negotiation_portal');
                        if (newCard) {
                            var newRounds = newCard.getAttribute('data-rounds');
                            var newState = newCard.getAttribute('data-state');
                            if (newRounds !== currentRounds || newState !== currentState) {
                                window.location.reload();
                            }
                        }
                    }).catch(function() {});
            }
        }, 3000);
    }
})();
